/* ============ data-globals.d.ts — types for the big unconverted .js data files ============
 * Four large data files stay in JS and assign onto the global G at load time:
 *   src/data/pokedex.js       -> G.DEX, G.DEX_BY, G.getPokemon(dex)
 *   src/data/sprites-meta.js  -> G.SPRITE_META
 *   src/data/changelog.js     -> G.CHANGELOG
 *   src/data/lang-en.js       -> G.I18n.add({...})  (nothing else; I18n itself is
 *                                already converted in src/core/i18n.ts)
 *
 * G cannot be redeclared (it stays `declare const G: Record<string, any>` in
 * src/global.d.ts), so the precise types are exported here instead and used
 * where autocomplete matters:
 *
 *   import type { PokedexEntry, GGlobals } from '../types/data-globals';
 *
 *   const p = G.DEX[0] as PokedexEntry;
 *   const g = G as unknown as GGlobals & Record<string, any>;
 *   const list: PokedexEntry[] = g.DEX;
 */

/** One entry of G.DEX (src/data/pokedex.js, generated by tools/fetch_pokedex.py).
 *  966 entries. The field is `dex`, not `id`; numbers are the national dex
 *  numbers with gaps (1..1024), so `dex !== index + 1`. Order is ascending. */
export interface PokedexEntry {
  /** National dex number (gaps exist, e.g. 954 is missing). */
  dex: number;
  name: string;
  /** 1-2 type keys, e.g. ['grass','poison']. */
  types: string[];
  /** Derived game stats (from base stats). */
  hp: number;
  spd: number;
  /** atk/sa: attack ratio (1.0 baseline), pa: physical-attack damage factor. */
  atk: number;
  pa: number;
  sa: number;
  /** df/sd: base Defense / Special Defense. */
  df: number;
  sd: number;
  /** Gacha rarity 1 (common) .. 5 (legendary). */
  rarity: number;
  /** Base stat total. */
  bst: number;
  /** Offered as a starter pick. */
  starter: boolean;
  /** Generation / banner 1 (Kanto) .. 9 (Paldea). */
  gen: number;
  /** Legendary or singular — only drops from rifts (~87 entries). */
  leg?: boolean;
}

/** One value of G.SPRITE_META (src/data/sprites-meta.js, generated by
 *  tools/fetch_sprites.py). Keys are dex numbers written as object literals
 *  (numeric literals, string keys at runtime). Loose on purpose: nested
 *  animation geometry varies per sprite. Known keys: s shadow size,
 *  a animations {Idle,Walk,Attack,...} each {w,h,n,r,d[],ax,ay},
 *  sh shiny flag, sa shiny geometry delta, sm shiny anims missing, hv hover flag. */
export interface SpriteMetaEntry {
  [k: string]: any;
}

/** One entry of G.CHANGELOG (src/data/changelog.js), newest first.
 *  Every bilingual string is a [spanish, english] pair; section items are
 *  arrays of those pairs. */
export interface ChangelogEntry {
  /** ISO date 'YYYY-MM-DD'. */
  d: string;
  /** Headline [es, en]. */
  title: [string, string];
  /** Sections: new stuff, changes, fixes — each [es, en] line. */
  new?: [string, string][];
  chg?: [string, string][];
  fix?: [string, string][];
}

/** G members written by the unconverted data files above. Cast `G` to this
 *  (intersected with `Record<string, any>`) when you want typed access: */
export interface GGlobals {
  DEX: PokedexEntry[];
  DEX_BY: Record<number, PokedexEntry>;
  getPokemon(dex: number): PokedexEntry | undefined;
  SPRITE_META: Record<number, SpriteMetaEntry>;
  CHANGELOG: ChangelogEntry[];
}
